# Simple arithmetic encoder
package ArithmeticCoder;

sub new {
    my $class = shift;
    return bless {
        output => '',
        cc => [(0) x (1000000 * 2)],
        range => 1,
        fraction => 0,
        radix => 255,
        pending_bytes => 0,
    }, $class;
}

sub put_bit {
    my ($self, $bit, $ctx) = @_;
    my $counts_idx = $ctx * 2;
    my $c0 = $self->{cc}[$counts_idx];
    my $c1 = $self->{cc}[$counts_idx + 1];

    my $split = int($self->{range} * ($c0 + 1) / ($c0 + $c1 + 2));

    if ($bit) {
        $self->{fraction} += $split;
        $self->{range} -= $split;
    } else {
        $self->{range} = $split;
    }

    $self->{cc}[$counts_idx + $bit]++;

    # Handle range reduction
    while ($self->{range} < $self->{radix}) {
        my $byte = int($self->{fraction} / ($self->{range} + 1)) + 1;
        $self->{output} .= chr($byte & 0xFF);
        $self->{range} *= $self->{radix};
        $self->{fraction} = int($self->{fraction} % ($self->{range} / $self->{radix})) * $self->{radix};
    }
}

sub put_integer {
    my ($self, $val, $nbits, $ctx) = @_;
    my $subtract_it = 1 << $nbits;
    $val += $subtract_it;

    my $bit_len = $nbits;
    my $ctx_base = $ctx * 99;

    # Unary code for actual bit length
    while (!($val & (1 << $bit_len))) {
        $self->put_bit(0, $bit_len + $ctx_base);
        $bit_len++;
    }
    $self->put_bit(1, $bit_len + $ctx_base);
    $bit_len--;

    # Binary code for remaining bits
    for my $i (0 .. $bit_len - 1) {
        my $b = ($val >> ($bit_len - 1 - $i)) & 1;
        $self->put_bit($b, $ctx_base);
    }
}

sub flush {
    my $self = shift;
    while ($self->{range} > 1) {
        my $byte = int($self->{fraction} / int($self->{range} / $self->{radix})) + 1;
        $self->{output} .= chr($byte & 0xFF);
        $self->{range} = int($self->{range} / $self->{radix});
        $self->{fraction} = int($self->{fraction} % ($self->{range} * $self->{radix})) / $self->{range};
    }
    return $self->{output};
}

