$range = 1; $frac = 0; $radix = 255;
sub pb {
    my ($b,$c) = @_;
    my $c0 = $cc{"$c:0"} // 0; my $c1 = $cc{"$c:1"} // 0;
    my $s = int($range * (1 + $c0) / ($c0 + $c1 + 2));
    if ($b) { $frac += $s; $range -= $s; } else { $range = $s; }
    $cc{"$c:$b"}++;
    while ($range < $radix && $range > 0) {
        push @out, (int($frac / $range) + 1) & 0xFF;
        $frac = ($frac % $range) * $radix; $range *= $radix;
    }
}
sub pi {
    my ($v,$n,$c) = @_; my $e = $v + (1 << $n); my $t = $n; my $cb = $c * 99;
    while (!($e & (1 << $t))) { pb(0, $t + $cb); $t++; }
    pb(1, $t + $cb); $t--;
    for my $i (0 .. $t - 1) { pb(($e >> ($t - 1 - $i)) & 1, $cb); }
}
pi(length($data), 9, 0);
for (0 .. length($data)-1) {
    my $b = ord(substr($data, $_, 1));
    my $s = ($b < 128) ? $b : $b - 256;
    pb(0, 1); pi($s, 4, 9);
}
open my $f, '>:raw', '/app/data.comp' or die;
my $packed = pack('C*', @out);
print $f $packed;
close $f;
print STDERR scalar(@out) . " bytes\n";
ENDSCRIPT
perl /app/comp.pl 2>&1
